css:
.fx-aur{position:relative;overflow:hidden;min-height:100vh;display:grid;place-items:center;text-align:center;padding:2em;background:var(--surface)}
.fx-aur .blob{position:absolute;border-radius:50%;filter:blur(80px);opacity:.55;animation:fxaur calc(20s/var(--speed)) ease-in-out infinite alternate}
.fx-aur .b1{width:46vmax;height:46vmax;left:-10%;top:-22%;background:var(--primary)}
.fx-aur .b2{width:40vmax;height:40vmax;right:-8%;top:8%;background:var(--accent);animation-delay:-7s}
.fx-aur .b3{width:34vmax;height:34vmax;left:28%;bottom:-32%;background:color-mix(in srgb,var(--primary) 50%,var(--accent));animation-delay:-12s}
.fx-aur .in{position:relative;display:grid;gap:1.1em;justify-items:center;max-width:760px}
.fx-aur h1{font-size:clamp(2.6em,7vw,5em)}.fx-aur p{opacity:.78;font-size:1.15em;max-width:46ch}
.fx-aur .btn{margin-top:.4em;padding:.95em 1.8em;border-radius:var(--radius);background:var(--text);color:var(--surface);font-weight:700;text-decoration:none}
@keyframes fxaur{to{transform:translate(9vmax,7vmax) scale(1.18)}}
@media(prefers-reduced-motion:reduce){.fx-aur .blob{animation:none}}
